interfaces.interface:
interface TimelineState {
  // Existing fields...
  zoomLevel: number;             // 0.1 to 5.0
  pixelsPerSecond: number;       // Computed: basePixelsPerSecond * zoomLevel
  setZoomLevel: (level: number) => void;
  zoomIn: () => void;           // Multiply by 1.2, max 5.0
  zoomOut: () => void;          // Divide by 1.2, min 0.1
  fitToTimeline: () => void;    // Calculate zoom to fit all clips
}

interface ZoomControlsProps {
  zoomLevel: number;
  onZoomIn: () => void;
  onZoomOut: () => void;
  onFit: () => void;
  onZoomChange: (level: number) => void;
}
